package com.example.incidentapp.viewmodel;
import androidx.lifecycle.*;import com.example.incidentapp.model.*;import com.example.incidentapp.repository.*;import com.example.incidentapp.session.SessionManager;import com.example.incidentapp.util.SlaUtils;import java.util.*;import retrofit2.*;
public class HomeViewModel extends ViewModel{private final IncidenteRepository repo=new IncidenteRepository();private final NotificacionRepository nr=new NotificacionRepository();private final LocalCacheRepository local=new LocalCacheRepository();private final MutableLiveData<List<Incidente>> incidentes=new MutableLiveData<>(Collections.emptyList());private final MutableLiveData<Boolean> loading=new MutableLiveData<>(false);private final MutableLiveData<Integer> noLeidas=new MutableLiveData<>(0);private final Set<Integer> marcando=new HashSet<>();public LiveData<List<Incidente>> getIncidentes(){return incidentes;}public LiveData<Boolean> getLoading(){return loading;}public LiveData<Integer> getNoLeidas(){return noLeidas;}public void cargarResumen(){int uid=SessionManager.getInstance().getIdUsuario();local.cargarIncidentes(uid,null,null,l->{if(l!=null&&!l.isEmpty())incidentes.setValue(l);});loading.setValue(true);repo.obtenerIncidentes(null,null).enqueue(new Callback<IncidentesResponse>(){public void onResponse(Call<IncidentesResponse>c,Response<IncidentesResponse>r){loading.setValue(false);if(r.isSuccessful()&&r.body()!=null&&r.body().getIncidentes()!=null){List<Incidente> l=r.body().getIncidentes();incidentes.setValue(l);local.guardarIncidentes(uid,l);for(Incidente i:l)if(SlaUtils.estaVencidoActivo(i)&&marcando.add(i.getId()))repo.marcarVencimientoSla(i.getId()).enqueue(new Callback<MensajeResponse>(){public void onResponse(Call<MensajeResponse>x,Response<MensajeResponse>rr){marcando.remove(i.getId());if(rr.isSuccessful()){i.setEstado("No Resuelto");incidentes.setValue(new java.util.ArrayList<>(l));}}public void onFailure(Call<MensajeResponse>x,Throwable t){marcando.remove(i.getId());}});}}public void onFailure(Call<IncidentesResponse>c,Throwable t){loading.setValue(false);}});}public void cargarNotificaciones(){nr.obtenerNotificaciones(true,20).enqueue(new Callback<NotificacionesResponse>(){public void onResponse(Call<NotificacionesResponse>c,Response<NotificacionesResponse>r){if(r.isSuccessful()&&r.body()!=null)noLeidas.setValue(r.body().getNoLeidas());}public void onFailure(Call<NotificacionesResponse>c,Throwable t){}});}}
